WITH valid AS (SELECT *, DATE_TRUNC('MONTH', starts_on) AS starts_on_period, COALESCE(channel, 'NONE') AS channel_filled FROM promotions WHERE channel IS NOT NULL AND promo_code = 'SPRING10') SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM valid a LEFT JOIN promotions pr ON a.channel <=> pr.channel AND a.starts_on >= pr.starts_on AND a.starts_on < pr.ends_on + INTERVAL '7' DAY
